 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            if len(cells) >= 2:
                boxes.append((color, min(x for x,y in cells), max(x for x,y in cells), min(y for x,y in cells), max(y for x,y in cells)))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            containing = [b for b in boxes if b[0] != color and b[1] <= r <= b[2] and b[3] <= c <= b[4]]
            if containing:
                # The enclosing solid object determines the repaired pixel.
                out[r][c] = min(containing, key=lambda b:(b[2]-b[1]+1)*(b[4]-b[3]+1))[0]
            elif not any(b[0] == color and b[1] <= r <= b[2] and b[3] <= c <= b[4] for b in boxes):
                out[r][c] = bg
    return out
